<meta name="component" content="WorldFieldPage">

<!-- The normal page, in play over the 3D scene: a hostile boss (targeted,
     casting) with its telegraph cone, a friend who speaks, the player, a
     merchant, each with its nameplate and selection ring; loot of every
     rarity on the ground, a chest's prompt, waypoints of every kind (one off
     the screen's right edge, held to it), a path line, a placement ghost
     either way and the damage numbers of a hit. -->
<div id="World">
  <Nameplate entity={$nameplate_default.entity} at={$nameplate_default.at} height={$nameplate_default.height} name={$nameplate_default.name} title={$nameplate_default.title} level={$nameplate_default.level} reaction={$nameplate_default.reaction} health={$nameplate_default.health} shield={$nameplate_default.shield} castName={$nameplate_default.castName} castProgress={$nameplate_default.castProgress} icon={$nameplate_default.icon} boss={$nameplate_default.boss} targeted={$nameplate_default.targeted} maxDistance={$nameplate_default.maxDistance} />
  <Nameplate entity={$nameplate_friendly.entity} at={$nameplate_friendly.at} height={$nameplate_friendly.height} name={$nameplate_friendly.name} title={$nameplate_friendly.title} level={$nameplate_friendly.level} reaction={$nameplate_friendly.reaction} health={$nameplate_friendly.health} shield={$nameplate_friendly.shield} castName={$nameplate_friendly.castName} castProgress={$nameplate_friendly.castProgress} icon={$nameplate_friendly.icon} boss={$nameplate_friendly.boss} targeted={$nameplate_friendly.targeted} maxDistance={$nameplate_friendly.maxDistance} />
  <Nameplate entity={$nameplate_player.entity} at={$nameplate_player.at} height={$nameplate_player.height} name={$nameplate_player.name} title={$nameplate_player.title} level={$nameplate_player.level} reaction={$nameplate_player.reaction} health={$nameplate_player.health} shield={$nameplate_player.shield} castName={$nameplate_player.castName} castProgress={$nameplate_player.castProgress} icon={$nameplate_player.icon} boss={$nameplate_player.boss} targeted={$nameplate_player.targeted} maxDistance={$nameplate_player.maxDistance} />
  <Nameplate entity={$nameplate_neutral.entity} at={$nameplate_neutral.at} height={$nameplate_neutral.height} name={$nameplate_neutral.name} title={$nameplate_neutral.title} level={$nameplate_neutral.level} reaction={$nameplate_neutral.reaction} health={$nameplate_neutral.health} shield={$nameplate_neutral.shield} castName={$nameplate_neutral.castName} castProgress={$nameplate_neutral.castProgress} icon={$nameplate_neutral.icon} boss={$nameplate_neutral.boss} targeted={$nameplate_neutral.targeted} maxDistance={$nameplate_neutral.maxDistance} />
  <LootLabel entity={$lootLabel_default.entity} at={$lootLabel_default.at} height={$lootLabel_default.height} name={$lootLabel_default.name} count={$lootLabel_default.count} rarity={$lootLabel_default.rarity} />
  <LootLabel entity={$lootLabel_common.entity} at={$lootLabel_common.at} height={$lootLabel_common.height} name={$lootLabel_common.name} count={$lootLabel_common.count} rarity={$lootLabel_common.rarity} />
  <LootLabel entity={$lootLabel_uncommon.entity} at={$lootLabel_uncommon.at} height={$lootLabel_uncommon.height} name={$lootLabel_uncommon.name} count={$lootLabel_uncommon.count} rarity={$lootLabel_uncommon.rarity} />
  <LootLabel entity={$lootLabel_rare.entity} at={$lootLabel_rare.at} height={$lootLabel_rare.height} name={$lootLabel_rare.name} count={$lootLabel_rare.count} rarity={$lootLabel_rare.rarity} />
  <LootLabel entity={$lootLabel_legendary.entity} at={$lootLabel_legendary.at} height={$lootLabel_legendary.height} name={$lootLabel_legendary.name} count={$lootLabel_legendary.count} rarity={$lootLabel_legendary.rarity} />
  <InteractionPrompt entity={$interactionPrompt_default.entity} at={$interactionPrompt_default.at} height={$interactionPrompt_default.height} action={$interactionPrompt_default.action} verb={$interactionPrompt_default.verb} name={$interactionPrompt_default.name} disabled={$interactionPrompt_default.disabled} reason={$interactionPrompt_default.reason} maxDistance={$interactionPrompt_default.maxDistance} />
  <Waypoint entity={$waypoint_default.entity} at={$waypoint_default.at} height={$waypoint_default.height} kind={$waypoint_default.kind} icon={$waypoint_default.icon} label={$waypoint_default.label} distance={$waypoint_default.distance} units={$waypoint_default.units} />
  <Waypoint entity={$waypoint_ping.entity} at={$waypoint_ping.at} height={$waypoint_ping.height} kind={$waypoint_ping.kind} icon={$waypoint_ping.icon} label={$waypoint_ping.label} distance={$waypoint_ping.distance} units={$waypoint_ping.units} />
  <Waypoint entity={$waypoint_danger.entity} at={$waypoint_danger.at} height={$waypoint_danger.height} kind={$waypoint_danger.kind} icon={$waypoint_danger.icon} label={$waypoint_danger.label} distance={$waypoint_danger.distance} units={$waypoint_danger.units} />
  <Waypoint entity={$waypoint_ally.entity} at={$waypoint_ally.at} height={$waypoint_ally.height} kind={$waypoint_ally.kind} icon={$waypoint_ally.icon} label={$waypoint_ally.label} distance={$waypoint_ally.distance} units={$waypoint_ally.units} />
  <Waypoint entity={$waypoint_loot.entity} at={$waypoint_loot.at} height={$waypoint_loot.height} kind={$waypoint_loot.kind} icon={$waypoint_loot.icon} label={$waypoint_loot.label} distance={$waypoint_loot.distance} units={$waypoint_loot.units} />
  <Waypoint entity={$waypoint_offscreen.entity} at={$waypoint_offscreen.at} height={$waypoint_offscreen.height} kind={$waypoint_offscreen.kind} icon={$waypoint_offscreen.icon} label={$waypoint_offscreen.label} distance={$waypoint_offscreen.distance} units={$waypoint_offscreen.units} />
  <SpeechBubble entity={$speechBubble_default.entity} at={$speechBubble_default.at} height={$speechBubble_default.height} speaker={$speechBubble_default.speaker} text={$speechBubble_default.text} shout={$speechBubble_default.shout} />
  <SelectionRing entity={$selectionRing_default.entity} at={$selectionRing_default.at} radius={$selectionRing_default.radius} reaction={$selectionRing_default.reaction} hover={$selectionRing_default.hover} segmented={$selectionRing_default.segmented} />
  <SelectionRing entity={$selectionRing_hostile.entity} at={$selectionRing_hostile.at} radius={$selectionRing_hostile.radius} reaction={$selectionRing_hostile.reaction} hover={$selectionRing_hostile.hover} segmented={$selectionRing_hostile.segmented} />
  <SelectionRing entity={$selectionRing_neutral.entity} at={$selectionRing_neutral.at} radius={$selectionRing_neutral.radius} reaction={$selectionRing_neutral.reaction} hover={$selectionRing_neutral.hover} segmented={$selectionRing_neutral.segmented} />
  <SelectionRing entity={$selectionRing_hover.entity} at={$selectionRing_hover.at} radius={$selectionRing_hover.radius} reaction={$selectionRing_hover.reaction} hover={$selectionRing_hover.hover} segmented={$selectionRing_hover.segmented} />
  <Telegraph entity={$telegraph_default.entity} at={$telegraph_default.at} shape={$telegraph_default.shape} radius={$telegraph_default.radius} inner={$telegraph_default.inner} angle={$telegraph_default.angle} width={$telegraph_default.width} direction={$telegraph_default.direction} progress={$telegraph_default.progress} friendly={$telegraph_default.friendly} />
  <Telegraph entity={$telegraph_disc.entity} at={$telegraph_disc.at} shape={$telegraph_disc.shape} radius={$telegraph_disc.radius} inner={$telegraph_disc.inner} angle={$telegraph_disc.angle} width={$telegraph_disc.width} direction={$telegraph_disc.direction} progress={$telegraph_disc.progress} friendly={$telegraph_disc.friendly} />
  <PathLine at={$pathLine_default.at} size={$pathLine_default.size} path={$pathLine_default.path} reach={$pathLine_default.reach} endX={$pathLine_default.endX} endY={$pathLine_default.endY} label={$pathLine_default.label} invalid={$pathLine_default.invalid} />
  <PlacementGhost at={$placementGhost_default.at} width={$placementGhost_default.width} depth={$placementGhost_default.depth} rotation={$placementGhost_default.rotation} cells={$placementGhost_default.cells} valid={$placementGhost_default.valid} label={$placementGhost_default.label} range={$placementGhost_default.range} />
  <PlacementGhost at={$placementGhost_valid.at} width={$placementGhost_valid.width} depth={$placementGhost_valid.depth} rotation={$placementGhost_valid.rotation} cells={$placementGhost_valid.cells} valid={$placementGhost_valid.valid} label={$placementGhost_valid.label} range={$placementGhost_valid.range} />
  <DamageNumbers hits={$damageNumbers_default_hits} />
  <OverheadBars bars={$overheadBars_default_bars} height={$overheadBars_default.height} />
</div>

<style>
#World { width: stretch; height: stretch; }
</style>
